import React, { useState, Fragment, useEffect } from "react";
import { Row, Col, Card, Tab, Tabs, Modal } from "react-bootstrap";
import NotEnrollPatients from "./Patient/PatientList";
import ActiveANCPatients from "./Patient/ActiveANCPatientList";
//import VisualisationHome from './Visualisation/Index'
import { Link } from "react-router-dom";
import Button from "@material-ui/core/Button";
import { FaUserPlus, FaChartLine, FaList } from "react-icons/fa";
import PmtctEntryPoint from "./PmtctServices/PmtctEntryPoint";
import ANCPatients from "./Patient/ActiveANCPatientList";
import PmtctPatients from "./Patient/PmtctPatients";
import CheckedInPatient from "./Patient/CheckedInPatient";
import ActivePmtctHtsPatients from "./Patient/ActivePmtctHtsPatientList";
import HivExposedInfantList from "./Patient/HivExposedInfantList";
import { usePermissions } from "../../hooks/usePermissions";
import PMTCTDashboard from "./Dashboard/PMTCTDashboard";
import axios from "axios";
import { url as baseUrl, token } from "../../api";

//import PageTitle from "./../layouts/PageTitle";
const divStyle = {
  borderRadius: "2px",
  fontSize: 14,
};

const Home = (props) => {
    const { hasRDErole, hasStrictylyRDE } = usePermissions();

  const [key, setKey] = useState("home");
  const [modalShow, setModalShow] = useState(false);
  const [showDashboard, setShowDashboard] = useState(false);
  const [migrationAlert, setMigrationAlert] = useState(null);

  // LV3-1965 §10: the one-time "map existing HTS records" backfill prompt. Same shape as the
  // migration-status check right below — a status endpoint on mount, a modal only if there's
  // still something to do. htsBackfillPrompt holds {recordsMapped, patientsAffected} (the dry
  // run) while it's pending, or null once dismissed-for-this-visit or completed.
  // htsBackfillProgress holds {processed, total} while the background run is in flight, polled
  // from hts-backfill-progress — this is a single collective pass over the whole backlog, not a
  // per-patient thing, so there's exactly one bar for the entire run. htsBackfillDone carries the
  // final {recordsMapped, patientsAffected} summary once polling detects it's finished.
  const [htsBackfillPrompt, setHtsBackfillPrompt] = useState(null);
  const [htsBackfillProgress, setHtsBackfillProgress] = useState(null);
  const [htsBackfillDone, setHtsBackfillDone] = useState(null);

  useEffect(() => {
    setKey("home");
  }, []);

  // Check migration status on mount
  useEffect(() => {
    axios
      .get(`${baseUrl}pmtct/anc/migration-status`, {
        headers: { Authorization: `Bearer ${token}` },
      })
      .then((res) => {
        if (res.data && res.data.migrationRequired) {
          setMigrationAlert(res.data.unmigratedCount);
        }
      })
      .catch(() => {
        // Silently ignore — endpoint may not exist on older backend
      });
  }, []);

  // Check HTS backfill status on mount — only ever shows the modal if it hasn't been run yet.
  useEffect(() => {
    axios
      .get(`${baseUrl}pmtct/anc/hts-backfill-status`, {
        headers: { Authorization: `Bearer ${token}` },
      })
      .then((res) => {
        const data = res.data;
        if (data && !data.completed && (data.recordsMapped || 0) > 0) {
          setHtsBackfillPrompt(data);
        }
      })
      .catch(() => {
        // Silently ignore — best-effort, must never block the landing page.
      });
  }, []);

  // POST just starts the background run and returns immediately (202) — the progress bar comes
  // entirely from polling hts-backfill-progress, not from this call's response.
  const runHtsBackfill = () => {
    setHtsBackfillProgress({ processed: 0, total: htsBackfillPrompt.recordsMapped });
    axios
      .post(
        `${baseUrl}pmtct/anc/hts-backfill`,
        {},
        { headers: { Authorization: `Bearer ${token}` } }
      )
      .then(() => pollHtsBackfillProgress())
      .catch(() => setHtsBackfillProgress(null));
  };

  const pollHtsBackfillProgress = () => {
    axios
      .get(`${baseUrl}pmtct/anc/hts-backfill-progress`, {
        headers: { Authorization: `Bearer ${token}` },
      })
      .then((res) => {
        const data = res.data;
        setHtsBackfillProgress({ processed: data.recordsMapped || 0, total: data.totalRecords || 0 });

        if (data.running) {
          setTimeout(pollHtsBackfillProgress, 1000);
          return;
        }

        // Finished — pull the authoritative summary (patientsAffected lives on the saved
        // status row, not the progress poll) and switch the modal into its done state.
        axios
          .get(`${baseUrl}pmtct/anc/hts-backfill-status`, {
            headers: { Authorization: `Bearer ${token}` },
          })
          .then((statusRes) => {
            setHtsBackfillProgress(null);
            setHtsBackfillDone(statusRes.data);
          })
          .catch(() => setHtsBackfillProgress(null));
      })
      .catch(() => setTimeout(pollHtsBackfillProgress, 1000));
  };

  return (
    <Fragment>
      {showDashboard ? (
        <PMTCTDashboard onNavigateToMenu={() => setShowDashboard(false)} />
      ) : (
        <>
          <Row>
            <Col xl={12}>
              <Card style={divStyle}>
                <Card.Body>
                  <div style={{
                    display: 'flex',
                    justifyContent: 'space-between',
                    alignItems: 'center',
                    marginBottom: '20px'
                  }}>
                    <h4 style={{ margin: 0, padding: 0 }}>PMTCT</h4>
                    <Button
                      variant="contained"
                      onClick={() => setShowDashboard(true)}
                      startIcon={<FaChartLine />}
                      style={{ backgroundColor: 'rgb(1, 77, 136)', color: '#fff' }}
                    >
                      Dashboard
                    </Button>
                  </div>
                  {migrationAlert && <Modal
                    show={true}
                    backdrop="static"
                    keyboard={false}
                    centered
                    animation={false}
                    dialogClassName="pmtct-migration-modal"
                  >
                    <style>{`.pmtct-migration-modal { max-width: 400px; }`}</style>
                    <Modal.Body style={{ padding: '0', textAlign: 'center' }}>
                      <div style={{ padding: '24px 24px 16px' }}>
                        <div style={{
                          backgroundColor: '#dc3545',
                          borderRadius: '8px',
                          padding: '14px 20px',
                          display: 'inline-flex',
                          alignItems: 'center',
                          gap: '10px',
                        }}>
                          <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="#fff" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                            <path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"/>
                            <line x1="12" y1="9" x2="12" y2="13"/>
                            <line x1="12" y1="17" x2="12.01" y2="17"/>
                          </svg>
                          <span style={{ color: '#fff', fontWeight: 600, fontSize: '15px' }}>
                            Migration Required
                          </span>
                        </div>
                      </div>
                      <div style={{ padding: '20px 28px 24px', backgroundColor: '#fff' }}>
                        <div style={{ marginBottom: '18px' }}>
                          <span style={{
                            color: '#dc3545',
                            fontSize: '28px',
                            fontWeight: 800,
                            display: 'block',
                            marginBottom: '4px',
                          }}>
                            {migrationAlert}
                          </span>
                          <span style={{
                            fontSize: '14px',
                            color: '#1a1a1a',
                            fontWeight: 600,
                            lineHeight: '1.5',
                          }}>
                            PMTCT HTS record{migrationAlert > 1 ? 's' : ''} must be migrated
                            before this module can be used.
                          </span>
                        </div>
                        <div style={{
                          backgroundColor: '#f5f5f5',
                          borderRadius: '8px',
                          padding: '16px',
                          marginBottom: '16px',
                          textAlign: 'left',
                          border: 'none',
                        }}>
                          <p style={{
                            fontSize: '12px',
                            color: '#555',
                            lineHeight: '1.7',
                            margin: 0,
                            fontWeight: 500,
                          }}>
                            <span style={{ fontWeight: 700, color: '#333', textTransform: 'uppercase', letterSpacing: '0.5px' }}>What to do: </span>
                            Contact your system administrator to run the
                            <span style={{
                              fontFamily: 'monospace',
                              fontWeight: 700,
                              color: '#dc3545',
                            }}> pmtct_hts_migration.sql </span>
                            script on the database provided during
                            <span style={{ fontWeight: 700 }}> pmtct-2.5.0</span> release.
                          </p>
                        </div>
                        <p style={{
                          fontSize: '11px',
                          color: '#adb5bd',
                          marginBottom: 0,
                          letterSpacing: '0.3px',
                        }}>
                          This module will unlock automatically after migration.
                        </p>
                      </div>
                    </Modal.Body>
                  </Modal>}

                  {/* LV3-1965 §10: one-time modal offering to map existing HTS records to
                      their pregnancy cycles. Only rendered while htsBackfillPrompt is set —
                      set once on mount if the backfill hasn't completed and there's actually
                      something to map; cleared for the rest of this visit on "Not now" (it
                      isn't gone for good — the completed flag isn't set, so it reappears next
                      visit), or once htsBackfillDone is populated after a real run. */}
                  {htsBackfillPrompt && (
                    <Modal
                      show={true}
                      backdrop="static"
                      keyboard={false}
                      centered
                      animation={false}
                      dialogClassName="pmtct-hts-backfill-modal"
                      onHide={() => setHtsBackfillPrompt(null)}
                    >
                      <style>{`.pmtct-hts-backfill-modal { max-width: 420px; }`}</style>
                      <Modal.Body style={{ padding: "24px 26px 22px" }}>
                        {htsBackfillDone ? (
                          <div style={{ textAlign: "center" }}>
                            <div
                              style={{
                                width: 40,
                                height: 40,
                                borderRadius: "50%",
                                backgroundColor: "#e6f3f0",
                                color: "#0e7c6b",
                                display: "flex",
                                alignItems: "center",
                                justifyContent: "center",
                                fontSize: 20,
                                fontWeight: 700,
                                margin: "0 auto 14px",
                              }}
                            >
                              ✓
                            </div>
                            <p style={{ margin: 0, fontSize: 14, fontWeight: 600 }}>
                              {htsBackfillDone.recordsMapped} record
                              {htsBackfillDone.recordsMapped === 1 ? "" : "s"} mapped across{" "}
                              {htsBackfillDone.patientsAffected} client
                              {htsBackfillDone.patientsAffected === 1 ? "" : "s"}.
                            </p>
                            <Button
                              variant="contained"
                              onClick={() => {
                                setHtsBackfillPrompt(null);
                                setHtsBackfillDone(null);
                              }}
                              style={{
                                marginTop: 18,
                                backgroundColor: "rgb(1, 77, 136)",
                                color: "#fff",
                              }}
                            >
                              Done
                            </Button>
                          </div>
                        ) : htsBackfillProgress ? (
                          <div style={{ textAlign: "center" }}>
                            <h5 style={{ margin: "0 0 6px", fontSize: "15.5px", fontWeight: 700 }}>
                              Mapping records…
                            </h5>
                            <p style={{ margin: "0 0 16px", fontSize: "13px", color: "#6b7280" }}>
                              {htsBackfillProgress.processed} of {htsBackfillProgress.total}
                            </p>
                            <div
                              style={{
                                height: 8,
                                borderRadius: 4,
                                backgroundColor: "#e6e9ee",
                                overflow: "hidden",
                              }}
                            >
                              <div
                                style={{
                                  height: "100%",
                                  borderRadius: 4,
                                  backgroundColor: "#0e7c6b",
                                  width: `${
                                    htsBackfillProgress.total > 0
                                      ? Math.min(
                                          100,
                                          Math.round(
                                            (htsBackfillProgress.processed / htsBackfillProgress.total) * 100
                                          )
                                        )
                                      : 0
                                  }%`,
                                  transition: "width 0.3s ease",
                                }}
                              />
                            </div>
                          </div>
                        ) : (
                          <>
                            <div
                              style={{
                                width: 36,
                                height: 36,
                                borderRadius: "50%",
                                backgroundColor: "#e6f3f0",
                                color: "#0e7c6b",
                                display: "flex",
                                alignItems: "center",
                                justifyContent: "center",
                                fontSize: 15,
                                fontWeight: 700,
                                marginBottom: 14,
                              }}
                            >
                              ↻
                            </div>
                            <h5 style={{ margin: "0 0 8px", fontSize: "15.5px", fontWeight: 700 }}>
                              Map existing HTS records to pregnancy cycles?
                            </h5>
                            <p style={{ margin: 0, fontSize: "13.5px", color: "#6b7280", lineHeight: 1.55 }}>
                              We found{" "}
                              <strong style={{ color: "#1a1a1a" }}>
                                {htsBackfillPrompt.recordsMapped} HIV test record
                                {htsBackfillPrompt.recordsMapped === 1 ? "" : "s"}
                              </strong>{" "}
                              for{" "}
                              <strong style={{ color: "#1a1a1a" }}>
                                {htsBackfillPrompt.patientsAffected} client
                                {htsBackfillPrompt.patientsAffected === 1 ? "" : "s"}
                              </strong>{" "}
                              that were documented on the HTS module but never linked to a
                              pregnancy cycle. Map them now so they show up on each client's
                              history.
                            </p>
                            <div
                              style={{
                                display: "flex",
                                gap: 10,
                                justifyContent: "flex-end",
                                marginTop: 20,
                              }}
                            >
                              <Button
                                variant="text"
                                onClick={() => setHtsBackfillPrompt(null)}
                                style={{ color: "#6b7280" }}
                              >
                                Not now
                              </Button>
                              <Button
                                variant="contained"
                                onClick={runHtsBackfill}
                                style={{ backgroundColor: "rgb(1, 77, 136)", color: "#fff" }}
                              >
                                Map them now
                              </Button>
                            </div>
                          </>
                        )}
                      </Modal.Body>
                    </Modal>
                  )}

                  {/* <!-- Nav tabs --> */}

                  <div className="custom-tab-1">
                    <Tabs
                      id="controlled-tab-example"
                      activeKey={key}
                      onSelect={(k) => setKey(k)}
                      className="mb-3"
                    >
                      {/* {hasRDErole ?     */}

                      <Tab eventKey="home" title="Find Patients">
                        <NotEnrollPatients />
                      </Tab>
                      {/* // :         */}

                      {!hasStrictylyRDE && (
                        <Tab eventKey="checked-in" title="Checked In Patients">
                          <CheckedInPatient />
                        </Tab>
                      )}
                      {/* //  } */}

                      <Tab eventKey="pmtct-hts" title="PMTCT HTS Patients">
                        <ActivePmtctHtsPatients />
                      </Tab>

                      <Tab eventKey="anc" title="ANC Patients">
                        <ANCPatients />
                      </Tab>

                      <Tab eventKey="pmtct" title="General PMTCT Patients">
                        <PmtctPatients />
                      </Tab>

                      <Tab eventKey="hei" title="HIV Exposed Infants">
                        <HivExposedInfantList />
                      </Tab>
                    </Tabs>
                  </div>
                </Card.Body>
              </Card>
            </Col>
          </Row>
        </>
      )}
      <PmtctEntryPoint
        route="/register-patient"
        show={modalShow}
        onHide={() => setModalShow(false)}
      />
    </Fragment>
  );
};

export default Home;
